// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(this));
        vm.assume(receiver.code.length == 0);
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(c), 2 ether);
        vm.deal(receiver, 0);

        uint256 before = receiver.balance;
        vm.prank(address(this));
        try c.sendTo(receiver, amount) {
            assertTrue(receiver.balance - before == amount, "receiver must be paid exactly amount");
        } catch {
            assertTrue(false, "sendTo reverted");
        }
    }
}
